static const char *csv_header="scheme,parameter_set,table_q,table_hash,timing_scope,implementation,production_variant,backend,frontend,mode,rng_in_timed_region,input_precomputed,frontend_materialized,timer_kind,sample_count,process_index,process_id,repetition,execution_order,input_seed,input_stream_id,cycles_total,cycles_per_output,cycles_per_attempt,attempts_per_output,rejections_per_output,accepted_outputs,source_words,logical_bits_per_output,physical_bits_per_output,checksum,replay_checksum,status,compiler_id,compiler_version,compiler_flags,git_commit,sampler_structure,stage_name,stage_block_size,instrumented,reconstructed_cycles_total,reconstructed_cycles_per_output,staged_full_cycles_per_output,fused_full_cycles_per_output,stage_sum_gap_percent,staging_overhead_percent";
static size_t env_size(const char*n,size_t d){const char*s=getenv(n);return s&&*s?(size_t)strtoull(s,0,10):d;}
static const char*env_string(const char*n,const char*d){const char*s=getenv(n);return s&&*s?s:d;}
static uint64_t checksum16(const uint16_t*x,size_t n){uint64_t h=UINT64_C(1469598103934665603);for(size_t i=0;i<n;i++){h^=x[i];h*=UINT64_C(1099511628211);}return h;}
static const char*table_hash(const frodo_sampler_params*p){return p->id==FRODO_PARAM_640?"2b95ba3ee428d74cac5c2f9eb44a34790dc111b6abdf8276c82e22c53219edcd":p->id==FRODO_PARAM_976?"f03c0a76dff335db1a83eca315c624efa2158c4ff82376e51bfffde2068ea94c":"63594c67d3b8e2ec16892f94ad746d3c1cf88245999d8681cb19dcb96165267e";}
typedef enum{IMPL_ORIGINAL,IMPL_SDA} implementation;
typedef struct{uint64_t cycles,checksum,replay;size_t attempts,rejections,words;int status;} measurement;
typedef struct{const frodo_sampler_params*p;implementation impl;const char*scope,*variant,*order,*structure,*stage,*instrumented;size_t n,process,rep,block;uint64_t seed,cycles,checksum,replay,reconstructed;size_t attempts,rejections,words;int status;const char*staged_cpo,*fused_cpo,*gap,*overhead;} row;
static const char*impl_name(implementation i){return i==IMPL_ORIGINAL?"original-reference":"sda-word-reference";}
static void emit(const row*r){double cpo=(double)r->cycles/r->n,apo=(double)r->attempts/r->n,rpo=(double)r->rejections/r->n,logical=r->impl==IMPL_ORIGINAL?16.0:(double)(r->p->sda_candidate_bits*r->attempts+r->n)/r->n,physical=(double)r->words*16/r->n;printf("Frodo,%s,%u,%s,%s,%s,%s,reference,%s,%s,false,true,%s,%s,%zu,%zu,%ld,%zu,%s,%" PRIu64 ",%s,%" PRIu64 ",%.6f,%.6f,%.6f,%.6f,%zu,%zu,%.6f,%.6f,%" PRIu64 ",%" PRIu64 ",%s,%s,%s,%s,%s,%s,%s,%zu,%s,",r->p->name,r->p->sda_q,table_hash(r->p),r->scope,impl_name(r->impl),r->variant,r->impl==IMPL_ORIGINAL?"original-word":"word-oriented",env_string("FRODO_BENCH_MODE","equal-size"),!strcmp(r->stage,"na")?"false":"true",BENCH_TIMER_KIND,r->n,r->process,(long)getpid(),r->rep,r->order,r->seed,WORD_STREAM,r->cycles,cpo,(double)r->cycles/r->attempts,apo,rpo,r->n,r->words,logical,physical,r->checksum,r->replay,r->status?"error":"ok",FRODO_COMPILER_ID,FRODO_COMPILER_VERSION,FRODO_COMPILER_FLAGS,FRODO_GIT_COMMIT,r->structure,r->stage,r->block,r->instrumented);if(r->reconstructed)printf("%" PRIu64 ",%.6f,",r->reconstructed,(double)r->reconstructed/r->n);else printf("na,na,");printf("%s,%s,%s,%s\n",r->staged_cpo,r->fused_cpo,r->gap,r->overhead);}
static int fused_call(implementation impl,const frodo_sampler_params*p,uint16_t*out,size_t n,const uint16_t*w,size_t wc,sdat_stats*st){if(impl==IMPL_ORIGINAL){int rc=frodo_original_sample_n_from_words(out,w,n,p->original_table);if(st){*st=(sdat_stats){n,0,n*2,n*16};}return rc;}return frodo_sda_word_sample_n(out,n,w,wc,p->sda_table,st);}
static int staged_call(implementation impl,const frodo_sampler_params*p,uint16_t*out,size_t n,const uint16_t*w,size_t wc,size_t block,frodo_stage_workspace*ws,sdat_stats*st,frodo_stage_timing*tm){return impl==IMPL_ORIGINAL?frodo_original_block_staged_sample_n(out,n,w,wc,p->original_table,block,ws,st,tm):frodo_sda_block_staged_sample_n(out,n,w,wc,p->sda_table,block,ws,st,tm);}
static measurement measure_fused(implementation impl,const frodo_sampler_params*p,uint16_t*out,uint16_t*replay,size_t n,const uint16_t*w,size_t wc){measurement m={0};uint64_t a=bench_timer_start();m.status=fused_call(impl,p,out,n,w,wc,0);uint64_t b=bench_timer_stop();m.cycles=b-a;m.checksum=checksum16(out,n);sdat_stats st={0};int rc=fused_call(impl,p,replay,n,w,wc,&st);m.replay=checksum16(replay,n);m.attempts=(size_t)st.attempts;m.rejections=(size_t)st.rejections;m.words=(size_t)(st.random_bytes/2);if(rc||m.checksum!=m.replay)m.status=-8;return m;}
static measurement measure_staged(implementation impl,const frodo_sampler_params*p,uint16_t*out,uint16_t*replay,size_t n,const uint16_t*w,size_t wc,size_t block,frodo_stage_workspace*ws){measurement m={0};uint64_t a=bench_timer_start();m.status=staged_call(impl,p,out,n,w,wc,block,ws,0,0);uint64_t b=bench_timer_stop();m.cycles=b-a;m.checksum=checksum16(out,n);sdat_stats st={0};int rc=staged_call(impl,p,replay,n,w,wc,block,ws,&st,0);m.replay=checksum16(replay,n);m.attempts=(size_t)st.attempts;m.rejections=(size_t)st.rejections;m.words=(size_t)(st.random_bytes/2);if(rc||m.checksum!=m.replay)m.status=-8;return m;}
static uint64_t stage_mark(void*ctx){(void)ctx;return bench_timer_mark();}
static void run_full(const frodo_sampler_params*p,implementation impl,const uint16_t*w,size_t wc,uint16_t*out,uint16_t*replay,size_t n,size_t proc,size_t rep,uint64_t seed,size_t block,frodo_stage_workspace*ws,int rows){measurement fused=measure_fused(impl,p,out,replay,n,w,wc);measurement staged=measure_staged(impl,p,out,replay,n,w,wc,block,ws);if(fused.checksum!=staged.checksum||fused.attempts!=staged.attempts||fused.rejections!=staged.rejections||fused.words!=staged.words){fused.status=staged.status=-9;}if(!rows)return;char scpo[32],fcpo[32],over[32];snprintf(scpo,sizeof scpo,"%.6f",(double)staged.cycles/n);snprintf(fcpo,sizeof fcpo,"%.6f",(double)fused.cycles/n);snprintf(over,sizeof over,"%.6f",100.0*((double)staged.cycles/fused.cycles-1.0));row fr={p,impl,"full-sampler-fused",impl==IMPL_ORIGINAL?"official-cdt-reference":"branchless-map-before-accept","first","fused","na","false",n,proc,rep,block,seed,fused.cycles,fused.checksum,fused.replay,0,fused.attempts,fused.rejections,fused.words,fused.status,"na","na","na","na"};row sr={p,impl,"full-sampler-block-staged","block-staged","second","block-staged","total","false",n,proc,rep,block,seed,staged.cycles,staged.checksum,staged.replay,0,staged.attempts,staged.rejections,staged.words,staged.status,scpo,fcpo,"na",over};emit(&fr);emit(&sr);}
static void run_stages(const frodo_sampler_params*p,implementation impl,const uint16_t*w,size_t wc,uint16_t*out,uint16_t*replay,size_t n,size_t proc,size_t rep,uint64_t seed,size_t block,frodo_stage_workspace*ws,int rows){frodo_stage_timing tm={stage_mark,0,0,0};int status=staged_call(impl,p,out,n,w,wc,block,ws,0,&tm);uint64_t checksum=checksum16(out,n);sdat_stats st={0};int rc=staged_call(impl,p,replay,n,w,wc,block,ws,&st,0);uint64_t replay_sum=checksum16(replay,n);if(rc||checksum!=replay_sum)status=-8;if(!rows)return;uint64_t reconstructed=tm.input_cycles+tm.mapping_cycles;row in={p,impl,"block-stage-input","block-staged","first","block-staged","input","true",n,proc,rep,block,seed,tm.input_cycles,checksum,replay_sum,reconstructed,(size_t)st.attempts,(size_t)st.rejections,(size_t)(st.random_bytes/2),status,"na","na","na","na"};row map={p,impl,"block-stage-mapping","block-staged","second","block-staged","mapping","true",n,proc,rep,block,seed,tm.mapping_cycles,checksum,replay_sum,reconstructed,(size_t)st.attempts,(size_t)st.rejections,(size_t)(st.random_bytes/2),status,"na","na","na","na"};emit(&in);emit(&map);}
static void run_case(const frodo_sampler_params*p,implementation impl,const char*scope,size_t n,size_t proc,size_t rep,const char*mode,size_t block,int rows){(void)mode;size_t wc=n*4+4096;uint16_t*w=malloc(wc*sizeof*w),*out=malloc(n*sizeof*out),*replay=malloc(n*sizeof*replay),*c=malloc(block*sizeof*c);uint8_t*s=malloc(block);if(!w||!out||!replay||!c||!s)exit(2);uint64_t seed=frodo_benchmark_seed((unsigned)p->id,proc,rep,1);frodo_benchmark_fill_words(w,wc,seed);frodo_stage_workspace ws={c,s,block};if(!strcmp(scope,"full"))run_full(p,impl,w,wc,out,replay,n,proc,rep,seed,block,&ws,rows);else if(!strcmp(scope,"stages"))run_stages(p,impl,w,wc,out,replay,n,proc,rep,seed,block,&ws,rows);else if(!strcmp(scope,"all")){run_full(p,impl,w,wc,out,replay,n,proc,rep,seed,block,&ws,rows);run_stages(p,impl,w,wc,out,replay,n,proc,rep,seed,block,&ws,rows);}else exit(3);free(w);free(out);free(replay);free(c);free(s);}
int main(void){const char*scope=env_string("FRODO_BENCH_SCOPE","full"),*mode=env_string("FRODO_BENCH_MODE","equal-size"),*selection=env_string("FRODO_BENCH_IMPLEMENTATION","all");size_t reps=env_size("FRODO_BENCH_REPETITIONS",31),warm=env_size("FRODO_BENCH_WARMUP",5),count=env_size("FRODO_BENCH_SAMPLE_COUNT",1048576),proc=env_size("FRODO_BENCH_PROCESS_INDEX",0),block=env_size("FRODO_STAGE_BLOCK_SIZE",DEFAULT_STAGE_BLOCK_SIZE);if(!block|| (strcmp(scope,"full")&&strcmp(scope,"stages")&&strcmp(scope,"all"))){fprintf(stderr,"invalid Frodo stage configuration\n");return 2;}puts(csv_header);for(int ii=0;ii<2;ii++){implementation impl=(implementation)ii;if(strcmp(selection,"all")&&strcmp(selection,ii?"sda":"original"))continue;for(size_t w=0;w<warm;w++){const frodo_sampler_params*p=frodo_get_sampler_params((frodo_param_id)(w%3));run_case(p,impl,scope,!strcmp(mode,"native-batch")?p->native_sample_count:count,proc,w,mode,block,0);}for(size_t rep=0;rep<reps;rep++)for(unsigned step=0;step<3;step++){const frodo_sampler_params*p=frodo_get_sampler_params((frodo_param_id)((step+rep)%3));run_case(p,impl,scope,!strcmp(mode,"native-batch")?p->native_sample_count:count,proc,rep,mode,block,1);}}return 0;}
